    11	namespace Utf8 {
    12	template <typename TStringBuilder>
    13	inline void encodeCodepoint(uint32_t codepoint32, TStringBuilder& str) {
    14	  // this function was optimize for code size on AVR
    15	
    16	  // a buffer to store the string in reverse
    17	  char buf[5];
    18	  char* p = buf;
    19	
    20	  *(p++) = 0;
    21	  if (codepoint32 < 0x80) {
    22	    *(p++) = char((codepoint32));
    23	  } else {
    24	    *(p++) = char((codepoint32 | 0x80) & 0xBF);
    25	    uint16_t codepoint16 = uint16_t(codepoint32 >> 6);
    26	    if (codepoint16 < 0x20) {  // 0x800
    27	      *(p++) = char(codepoint16 | 0xC0);
    28	    } else {
    29	      *(p++) = char((codepoint16 | 0x80) & 0xBF);
    30	      codepoint16 = uint16_t(codepoint16 >> 6);
    31	      if (codepoint16 < 0x10) {  // 0x10000
    32	        *(p++) = char(codepoint16 | 0xE0);
    33	      } else {
    34	        *(p++) = char((codepoint16 | 0x80) & 0xBF);
    35	        codepoint16 = uint16_t(codepoint16 >> 6);
    36	        *(p++) = char(codepoint16 | 0xF0);
    37	      }
    38	    }
    39	  }
    40	
    41	  while (*(--p)) {
    42	    str.append(*p);
    43	  }
    44	}
    45	}  // namespace Utf8
    46	}  // namespace ARDUINOJSON_NAMESPACE
